import{_ as r,o as s,c as t,a3 as n}from"./chunks/framework.BZKbe9n2.js";const p=JSON.parse('{"title":"Raumfeld-Lautsprecher","description":"","frontmatter":{},"headers":[],"relativePath":"de/administration/speakers.md","filePath":"de/administration/speakers.md"}'),a={name:"de/administration/speakers.md"};function d(i,e,o,u,l,c){return s(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="raumfeld-lautsprecher" tabindex="-1">Raumfeld-Lautsprecher <a class="header-anchor" href="#raumfeld-lautsprecher" aria-label="Permalink to &quot;Raumfeld-Lautsprecher&quot;">​</a></h1><p>Anthology spielt auf Teufel-Raumfeld-Lautsprechern. Der Server muss den Raumfeld-Host finden, und die Lautsprecher müssen den Server erreichen.</p><h2 id="den-raumfeld-host-finden" tabindex="-1">Den Raumfeld-Host finden <a class="header-anchor" href="#den-raumfeld-host-finden" aria-label="Permalink to &quot;Den Raumfeld-Host finden&quot;">​</a></h2><ul><li><strong>Mit Host-Netzwerk</strong> (<code>Network=host</code> in <code>anthology.pod</code>, <code>network_mode: host</code> in Compose) findet der Server den Raumfeld-Host selbst per Multicast (SSDP).</li><li><strong>Ohne Host-Netzwerk</strong> (der rootless Pod in der Vorgabe) erreicht Multicast den Server nicht. Trage die Adresse des Raumfeld-Hosts unter <strong>Einstellungen › Lautsprecher</strong> ein – die IP-Adresse der Basis oder des Lautsprechers, der als Host dient – oder setze <code>ANTHOLOGY_RAUMFELD_HOSTS</code>.</li></ul><p><strong>Einstellungen › Lautsprecher</strong> zeigt jedes System mit seinem Zustand und, wenn es nicht erreichbar ist, den Grund.</p><h2 id="die-lautsprecher-erreichen-den-server" tabindex="-1">Die Lautsprecher erreichen den Server <a class="header-anchor" href="#die-lautsprecher-erreichen-den-server" aria-label="Permalink to &quot;Die Lautsprecher erreichen den Server&quot;">​</a></h2><p>Die Lautsprecher holen die Musik per HTTP beim Server. Setze <code>ANTHOLOGY_OUTPUT_MEDIA_URL</code> auf die Adresse des Servers, wie die Lautsprecher sie sehen, zum Beispiel <code>http://192.168.1.10:8400</code>. Ohne diese Angabe nimmt der Server seine eigene Adresse auf dem Weg zu den Lautsprechern – hinter der Port-Weiterleitung des Pods ist das die Adresse des Containers, also setze die URL dort.</p><p>Lautsprecher und Server müssen im selben lokalen Netz sein; zum Internet muss kein Port geöffnet werden.</p><p>So spielst du auf Lautsprechern: <a href="/anthology/next/de/guide/speakers">Auf Lautsprechern abspielen</a>.</p>',9)])])}const m=r(a,[["render",d]]);export{p as __pageData,m as default};
